from collections import Counter


def transform(grid):
    """Compare equal-sized panels split by a solid line; mark aligned matches."""
    h, w = len(grid), len(grid[0])
    candidates = []
    for r, row in enumerate(grid):
        if len(set(row)) == 1 and r > 0 and h - r - 1 == r:
            candidates.append((grid[:r], grid[r + 1:]))
    for c in range(w):
        if len({grid[r][c] for r in range(h)}) == 1 and c > 0 and w - c - 1 == c:
            candidates.append(([row[:c] for row in grid], [row[c + 1:] for row in grid]))
    if not candidates:
        raise ValueError('No solid divider with equal-sized panels')
    first, second = candidates[0]
    shared = {v for row in first for v in row} & {v for row in second for v in row}
    if len(shared) != 1:
        raise ValueError(f'Expected a single shared panel color, got {shared}')
    common = next(iter(shared))
    return [[3 if a == b == common else common for a, b in zip(ra, rb)]
            for ra, rb in zip(first, second)]
